// Package members holds the rules for who gets WiFi access. It is pure:
// no I/O, no clock.
package members

import (
	"sort"
	"strings"

	"github.com/sauyon/nexudus-radius/internal/nexudus"
)

// Member is one row of the local database: a person allowed on the WiFi.
type Member struct {
	CoworkerID int64
	Email      string
	PIN        string
	UpdatedOn  string
}

func NormalizeEmail(s string) string {
	return strings.ToLower(strings.TrimSpace(s))
}

// Eligible returns the customers who should have access: active, holding an
// active contract, and with an email to log in with. Emails in the result
// are normalised. skippedNoEmail counts otherwise-eligible customers that
// were left out for lacking an email.
func Eligible(coworkers []nexudus.Coworker, contractHolders map[int64]struct{}) (eligible []nexudus.Coworker, skippedNoEmail int) {
	for _, cw := range coworkers {
		if !cw.Active {
			continue
		}
		if _, ok := contractHolders[cw.ID]; !ok {
			continue
		}
		cw.Email = NormalizeEmail(cw.Email)
		if cw.Email == "" {
			skippedNoEmail++
			continue
		}
		eligible = append(eligible, cw)
	}
	return eligible, skippedNoEmail
}

// Dedupe returns ms sorted by CoworkerID with at most one member per email.
// When several customers share an email the lowest ID wins, so the choice
// is stable from one sync to the next.
func Dedupe(ms []Member) (out []Member, dropped int) {
	sorted := append([]Member(nil), ms...)
	sort.Slice(sorted, func(i, j int) bool { return sorted[i].CoworkerID < sorted[j].CoworkerID })
	seen := make(map[string]struct{}, len(sorted))
	for _, m := range sorted {
		if _, dup := seen[m.Email]; dup {
			dropped++
			continue
		}
		seen[m.Email] = struct{}{}
		out = append(out, m)
	}
	return out, dropped
}
package nexudus

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"strconv"
	"strings"
	"sync"
	"time"
)

const (
	pageSize = 100
	maxPages = 10000
	maxBody  = 32 << 20
)

type Client struct {
	BaseURL  string
	Username string
	Password string
	// HTTP defaults to a client with a 30s timeout that does not follow
	// redirects.
	HTTP *http.Client
	// MinInterval is the minimum gap between requests. Nexudus allows 10
	// reads per 100ms; 50ms keeps well under that.
	MinInterval time.Duration

	mu   sync.Mutex
	last time.Time
}

// Go re-sends Authorization on same-site redirects, so none are followed.
var defaultHTTP = &http.Client{
	Timeout: 30 * time.Second,
	CheckRedirect: func(*http.Request, []*http.Request) error {
		return http.ErrUseLastResponse
	},
}

func (c *Client) throttle(ctx context.Context) error {
	if c.MinInterval <= 0 {
		return nil
	}
	c.mu.Lock()
	defer c.mu.Unlock()
	if wait := c.MinInterval - time.Since(c.last); wait > 0 {
		select {
		case <-time.After(wait):
		case <-ctx.Done():
			return ctx.Err()
		}
	}
	c.last = time.Now()
	return nil
}

// Get performs an authenticated GET and returns the body of a 200 response.
func (c *Client) Get(ctx context.Context, path string, q url.Values) ([]byte, error) {
	if err := c.throttle(ctx); err != nil {
		return nil, err
	}
	u := strings.TrimRight(c.BaseURL, "/") + path
	if len(q) > 0 {
		u += "?" + q.Encode()
	}
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, u, nil)
	if err != nil {
		return nil, err
	}
	req.SetBasicAuth(c.Username, c.Password)
	req.Header.Set("Accept", "application/json")

	hc := c.HTTP
	if hc == nil {
		hc = defaultHTTP
	}
	resp, err := hc.Do(req)
	if err != nil {
		return nil, fmt.Errorf("nexudus: GET %s: %w", path, err)
	}
	defer resp.Body.Close()
	body, err := io.ReadAll(io.LimitReader(resp.Body, maxBody))
	if err != nil {
		return nil, fmt.Errorf("nexudus: GET %s: %w", path, err)
	}
	if resp.StatusCode != http.StatusOK {
		return nil, fmt.Errorf("nexudus: GET %s: %s", path, resp.Status)
	}
	return body, nil
}

type page[T any] struct {
	Records     *[]T `json:"Records"`
	HasNextPage bool `json:"HasNextPage"`
}

// list fetches every page of a listing. Any failure discards what was
// fetched so far: a partial list must never be mistaken for a full one.
func list[T any](ctx context.Context, c *Client, path string, q url.Values) ([]T, error) {
	var all []T
	q.Set("size", strconv.Itoa(pageSize))
	for p := 1; p <= maxPages; p++ {
		q.Set("page", strconv.Itoa(p))
		body, err := c.Get(ctx, path, q)
		if err != nil {
			return nil, err
		}
		var pg page[T]
		if err := json.Unmarshal(body, &pg); err != nil {
			return nil, fmt.Errorf("nexudus: %s page %d: %w", path, p, err)
		}
		if pg.Records == nil {
			return nil, fmt.Errorf("nexudus: %s page %d: response has no Records", path, p)
		}
		all = append(all, *pg.Records...)
		if !pg.HasNextPage {
			return all, nil
		}
	}
	return nil, fmt.Errorf("nexudus: %s: more than %d pages", path, maxPages)
}

// ListCoworkers returns the active customers whose home location is
// businessID. AccessPincode is not populated.
func (c *Client) ListCoworkers(ctx context.Context, businessID int64) ([]Coworker, error) {
	q := url.Values{}
	q.Set("Coworker_Active", "true")
	q.Set("Coworker_InvoicingBusiness", strconv.FormatInt(businessID, 10))
	q.Set("orderBy", "Id")
	q.Set("dir", "0")
	return list[Coworker](ctx, c, "/api/spaces/coworkers", q)
}

// GetCoworker returns one customer with AccessPincode populated.
func (c *Client) GetCoworker(ctx context.Context, id int64) (Coworker, error) {
	body, err := c.Get(ctx, "/api/spaces/coworkers/"+strconv.FormatInt(id, 10), nil)
	if err != nil {
		return Coworker{}, err
	}
	var cw Coworker
	if err := json.Unmarshal(body, &cw); err != nil {
		return Coworker{}, fmt.Errorf("nexudus: coworker %d: %w", id, err)
	}
	return cw, nil
}

type contract struct {
	CoworkerID int64 `json:"CoworkerId"`
}

// ListActiveContractCoworkerIDs returns the IDs of customers holding at
// least one active contract issued by businessID.
func (c *Client) ListActiveContractCoworkerIDs(ctx context.Context, businessID int64) (map[int64]struct{}, error) {
	q := url.Values{}
	q.Set("CoworkerContract_Active", "true")
	q.Set("CoworkerContract_IssuedBy", strconv.FormatInt(businessID, 10))
	q.Set("orderBy", "Id")
	q.Set("dir", "0")
	contracts, err := list[contract](ctx, c, "/api/billing/coworkercontracts", q)
	if err != nil {
		return nil, err
	}
	ids := make(map[int64]struct{}, len(contracts))
	for _, ct := range contracts {
		if ct.CoworkerID != 0 {
			ids[ct.CoworkerID] = struct{}{}
		}
	}
	return ids, nil
}

