func TestPinUnmarshal(t *testing.T) {
	cases := []struct{ in, want string }{
		{`{"AccessPincode":"00321"}`, "00321"},
		{`{"AccessPincode":" 12345 "}`, "12345"},
		{`{"AccessPincode":12345}`, "12345"},
		{`{"AccessPincode":null}`, ""},
		{`{}`, ""},
	}
	for _, tc := range cases {
		var c Coworker
		if err := json.Unmarshal([]byte(tc.in), &c); err != nil {
			t.Fatalf("%s: %v", tc.in, err)
		}
		if string(c.AccessPincode) != tc.want {
			t.Errorf("%s: got %q want %q", tc.in, c.AccessPincode, tc.want)
		}
	}
	var c Coworker
	if err := json.Unmarshal([]byte(`{"AccessPincode":true}`), &c); err == nil {
		t.Error("boolean PIN should be an error")
	}
}

