// nextWait is how long Run sleeps after a pass, for r in [0, 1): somewhere
// from four fifths to six fifths of interval, so that several syncds started
// together on one Nexudus account drift apart instead of calling it at the
// same moment every time. After a failed pass it is a fifth of that: a pod is
// not ready until its first sync, and a full interval is a long time to wait
// on one 429.
func nextWait(interval time.Duration, failed bool, r float64) time.Duration {
	base := interval
	if failed {
		base = interval / 5
	}
	return base*4/5 + time.Duration(r*float64(base)*2/5)
}

